// Cartografia de Leituras: mesa editorial assimétrica, com rotas, fichas e grandes aberturas para o conteúdo.
import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { useTheme } from "@/contexts/ThemeContext";
import { toast } from "sonner";
import { ArrowLeft, ArrowRight, Bookmark, BookmarkCheck, BookOpen, Check, ChevronDown, ChevronRight, CircleHelp, Clock3, Compass, ExternalLink, Eye, FileText, Layers3, ListFilter, Map, Menu, Moon, Quote, Search, ShieldCheck, Sun, Users, X } from "lucide-react";
import { bibleBooks, bibleCategories, Book, themes, timeline } from "@/lib/bible-data";
import { canonComparison, glossary, people, studyModules, type Lesson, type StudyModule } from "@/lib/deep-data";
import { bookProfiles } from "@/lib/book-deep";
import { theologyCategories, theologyEntries, type TheologyEntry } from "@/lib/pentecostal-data";
import { completeBookEntries, type CompleteBook } from "@/lib/complete-book-data";
import GenesisRelationalDetail from "@/components/GenesisRelationalDetail";
import { apocalypseSources, apocalypseUnits, interpretationSchools, millennialViews, revelationChurches } from "@/lib/apocalypse-data";
import ApocalypseHub from "@/components/ApocalypseHub";
import { MapView } from "@/components/Map";
import { advancedDossiers, biblicalPlaces } from "@/lib/advanced-data";
import "@/advanced-atlas.css";
import "@/advanced-encyclopedia.css";
import "@/advanced-books.css";
import "@/cartography-polish.css";
import "@/genesis-relational.css";
import AdvancedBookLibrary from "@/components/AdvancedBookLibrary";
import BibliographyHub from "@/components/BibliographyHub";
import InteractiveAtlas from "@/components/InteractiveAtlas";
import BookDetailRouter from "@/components/BookDetailRouter";
import KnowledgeSearchPanel from "@/components/KnowledgeSearchPanel";
import EntityPanel from "@/components/EntityPanel";
import ExegesisSpotlight from "@/components/ExegesisSpotlight";
import AdvancedResearchHub from "@/components/AdvancedResearchHub";
import { bookFromEntityReference } from "@/lib/entity-graph";
import { RELATIONAL_BOOKS_URL, canonicalRelationalBookKey, normalizeRelationalBooksPayload, type RelationalBookData } from "@/lib/relational-book-data";
import { staticAsset } from "@/lib/static-asset";
import "@/relational-book.css";
import "@/mobile-home-polish.css";
import "@/advanced-research.css";
import "@/atlas-system-reinforcement.css";

type View = "overview" | "library" | "study" | "theology" | "people" | "canon" | "glossary" | "search" | "timeline" | "atlas" | "themes" | "apocalypse" | "bibliography";
const heroImage = staticAsset("assets/biblia-hero.jpg");
const atlasImage = heroImage;
const timelineImage = heroImage;
const studyImage = heroImage;
const brandMark = "";
const testamentShort = (testament: Book["testament"]) => testament === "Novo Testamento" ? "NT" : "AT";

function Mark({ compact = false }: { compact?: boolean }) { return <div className={`brand-lockup ${compact ? "brand-lockup--compact" : ""}`} aria-label="A Bíblia em visão geral">{brandMark ? <img src={brandMark} alt="" className="brand-mark" /> : <span className="brand-mark brand-mark--fallback">✶</span>}{!compact && <div><strong>A Bíblia</strong><span>em visão geral</span><small className="brand-notation">ATLAS · 66 LIVROS</small></div>}</div>; }
function Eyebrow({ children, number }: { children: ReactNode; number?: string }) { return <div className="section-eyebrow"><span className="eyebrow-line" />{number && <span className="eyebrow-number">{number}</span>}<span>{children}</span></div>; }
function Badge({ book }: { book: Book }) { return <span className={`book-badge ${book.testament === "Novo Testamento" ? "book-badge--new" : ""}`}>{testamentShort(book.testament)} · {book.short}</span>; }
function Stat({ value, label, icon: Icon }: { value: string; label: string; icon: typeof BookOpen }) { return <div className="stat-card"><div className="stat-icon"><Icon size={16} /></div><strong>{value}</strong><span>{label}</span></div>; }
function BookCard({ book, onOpen, saved, onSave }: { book: Book; onOpen: () => void; saved: boolean; onSave: () => void }) { const profile = bookProfiles[book.name]; return <article className="mini-book-card"><button className="mini-book-main" onClick={onOpen} aria-label={`Abrir resumo de ${book.name}`}><div className="mini-book-top"><Badge book={book} /><span className="chapter-count">{book.chapters} cap.</span></div><h3>{book.name}</h3><p>{book.summary}</p>{profile && <span className="mini-book-lens">Lente: {profile.lens}</span>}<div className="mini-book-foot"><span>{book.category}</span><ArrowRight size={15} /></div></button><button className={`save-button ${saved ? "is-saved" : ""}`} onClick={onSave} aria-label={saved ? `Remover ${book.name} dos salvos` : `Salvar ${book.name}`}>{saved ? <BookmarkCheck size={15} /> : <Bookmark size={15} />}</button></article>; }

function RouteMap() { return <div className="route-map" role="img" aria-label="Mapa esquemático da jornada narrativa da Bíblia"><div className="map-grid" /><svg viewBox="0 0 700 330" preserveAspectRatio="none" aria-hidden="true"><path className="map-river" d="M112 34 C148 80 155 123 142 166 S145 255 195 307" /><path className="map-route map-route--one" d="M108 258 C144 218 135 177 181 143 S286 108 338 132 S417 172 475 145 S522 92 585 67" /><path className="map-route map-route--two" d="M338 132 C368 172 347 225 392 261 S512 279 584 238" /><path className="map-route map-route--three" d="M181 143 C223 187 267 210 337 204 S442 190 475 145" />{[[108,258],[181,143],[338,132],[475,145],[585,67]].map(([cx, cy]) => <circle className="map-dot" key={`${cx}-${cy}`} cx={cx} cy={cy} r="7" />)}<circle className="map-dot map-dot--wine" cx="584" cy="238" r="7" /></svg><span className="map-label map-label--a">Origens</span><span className="map-label map-label--b">Êxodo</span><span className="map-label map-label--c">Reinos</span><span className="map-label map-label--d">Exílio</span><span className="map-label map-label--e">Jesus</span><span className="map-label map-label--f">Comunidades</span><div className="map-compass">N</div></div>; }

export default function Home() {
  const { theme, toggleTheme } = useTheme();
  const [view, setView] = useState<View>("overview"); const [activeBook, setActiveBook] = useState<Book | null>(null); const [activeStudy, setActiveStudy] = useState<{ module: StudyModule; lesson: Lesson } | null>(null); const [search, setSearch] = useState(""); const [testament, setTestament] = useState("Todos"); const [category, setCategory] = useState("Todos"); const [mobileNav, setMobileNav] = useState(false); const [note, setNote] = useState(""); const [focusPlaceId, setFocusPlaceId] = useState<string | null>(null); const [activeEntityId, setActiveEntityId] = useState<string | null>(null); const [relationalBooks, setRelationalBooks] = useState<Record<string, RelationalBookData>>({});
  const [savedIds, setSavedIds] = useState<string[]>(() => { try { return JSON.parse(localStorage.getItem("biblia-em-visao-saved") || "[]"); } catch { return []; } });
  useEffect(() => { localStorage.setItem("biblia-em-visao-saved", JSON.stringify(savedIds)); }, [savedIds]);
  useEffect(() => { fetch(RELATIONAL_BOOKS_URL).then(response => { if (!response.ok) throw new Error("Falha ao carregar o catálogo relacional."); return response.json(); }).then(payload => setRelationalBooks(normalizeRelationalBooksPayload(payload))).catch(() => setRelationalBooks({})); }, []);
  const books = useMemo(() => bibleBooks.filter(book => { const q = search.toLowerCase().trim(); return (!q || [book.name, book.author, book.category, book.summary, ...book.themes].join(" ").toLowerCase().includes(q)) && (testament === "Todos" || book.testament === testament) && (category === "Todos" || book.category === category); }), [search, testament, category]);
  const savedBooks = bibleBooks.filter(book => savedIds.includes(book.id));
  const go = (next: View) => { setView(next); setActiveBook(null); setActiveStudy(null); setFocusPlaceId(null); setMobileNav(false); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const openBook = (book: Book) => { setActiveBook(book); setActiveStudy(null); setView("library"); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const save = (id: string) => setSavedIds(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id]);
  return <div className="app-shell"><aside className={`side-rail ${mobileNav ? "side-rail--open" : ""}`}><div className="rail-top"><Mark /><button className="rail-close" onClick={() => setMobileNav(false)} aria-label="Fechar navegação"><X size={18} /></button></div><div className="rail-label">Índice da enciclopédia</div><nav className="rail-nav" aria-label="Navegação principal">{([ ["overview","Visão geral",Compass], ["study","Enciclopédia",FileText], ["library","Os 66 livros",BookOpen], ["people","Pessoas e povos",Users], ["canon","Cânones e manuscritos",Layers3], ["glossary","Glossário",CircleHelp], ["search","Busca avançada",Search], ["timeline","Períodos históricos",Clock3], ["atlas","Lugares e mapas",Map], ["themes","Temas bíblicos",Layers3], ["apocalypse","Apocalipse",Eye], ["bibliography","Bibliografia",FileText] ] as const).map(([id, label, Icon]) => <button key={id} className={`rail-link ${view === id && !activeBook ? "is-active" : ""}`} onClick={() => go(id)}><Icon size={17} /><span>{label}</span>{id === "library" && <small>66</small>}{id === "study" && <small>8</small>}{id === "apocalypse" && <small>11</small>}{id === "bibliography" && <small>66</small>}</button>)}</nav><div className="rail-rule" /><div className="rail-label">Consulta rápida</div><button className="rail-link" onClick={() => go("search")}><Search size={17} /><span>Buscar na rede</span></button><div className="rail-bottom"><div className="rail-progress"><span>Índice de referência</span><strong>66</strong><div><i style={{ width: "100%" }} /></div><small>Livros organizados por entidades</small></div><div className="rail-footnote">Enciclopédia visual<br />Cânon protestante · 66 livros</div></div></aside><main className="main-content"><header className="topbar"><button className="mobile-menu" onClick={() => setMobileNav(true)} aria-label="Abrir navegação"><Menu size={20} /></button><div className="topbar-context"><span>{activeBook ? "Verbete" : "Enciclopédia bíblica"}</span><span className="context-dot" /><strong>{activeBook?.name || ({ overview: "Visão geral", study: "Índice enciclopédico", library: "66 dossiês", people: "Pessoas", canon: "Cânones e manuscritos", glossary: "Glossário", search: "Busca e conexões", timeline: "Períodos históricos", atlas: "Atlas em camadas", themes: "Temas bíblicos", apocalypse: "Apocalipse e escatologia", bibliography: "Bibliografia acadêmica" } as Record<View, string>)[view]}</strong></div><div className="topbar-actions"><span className="canon-note">Cânon protestante · 66</span><button className="theme-toggle" onClick={toggleTheme} aria-label="Alternar tema">{theme === "dark" ? <Sun size={17} /> : <Moon size={17} />}</button></div></header>{view === "overview" && !activeBook && <Overview go={go} openBook={openBook} savedIds={savedIds} save={save} />}{view === "study" && !activeBook && <EncyclopediaHub go={go} />}{view === "library" && !activeBook && <Library books={books} search={search} setSearch={setSearch} testament={testament} setTestament={setTestament} category={category} setCategory={category} openBook={openBook} savedIds={savedIds} save={save} />}{view === "people" && !activeBook && <PeopleHub go={label => { setSearch(label); setView("library"); }} />}{view === "canon" && !activeBook && <CanonHub go={id => { setView("study"); setActiveStudy({ module: studyModules.find(item => item.id === id) || studyModules[0], lesson: (studyModules.find(item => item.id === id) || studyModules[0]).lessons[0] }); }} />}{view === "glossary" && !activeBook && <GlossaryHub />}{view === "search" && !activeBook && <KnowledgeSearchPanel openBook={openBook} onOpenEntity={setActiveEntityId} onFocusPlace={(placeId) => { setActiveEntityId(null); setFocusPlaceId(placeId); setView("atlas"); }} />}{view === "timeline" && !activeBook && <Timeline openBook={openBook} />}{view === "atlas" && !activeBook && <Atlas go={go} focusPlaceId={focusPlaceId} onFocusHandled={() => setFocusPlaceId(null)} />}{view === "themes" && !activeBook && <Themes go={label => { setSearch(label); setView("library"); }} />}{view === "apocalypse" && !activeBook && <ApocalypseHub />}{view === "bibliography" && !activeBook && <BibliographyHub />}{activeBook && <BookDetailRouter book={activeBook} saved={savedIds.includes(activeBook.id)} save={() => save(activeBook.id)} close={() => setActiveBook(null)} openBook={openBook} note={note} setNote={setNote} relationalData={relationalBooks} onFocusPlace={(placeId) => { setFocusPlaceId(placeId); setActiveBook(null); setView("atlas"); window.scrollTo({ top: 0, behavior: "smooth" }); }} />}</main><EntityPanel entityId={activeEntityId} close={() => setActiveEntityId(null)} onFocusPlace={(placeId) => { setActiveEntityId(null); setFocusPlaceId(placeId); setView("atlas"); }} onOpenEntity={setActiveEntityId} onOpenBook={(bookName) => { const target = bookFromEntityReference(bookName); if (target) { setActiveEntityId(null); openBook(target); } }} /><MobileBottomNav view={view} go={go} savedCount={savedBooks.length} /></div>;
}

function Overview({ go, openBook, savedIds, save }: { go: (view: View) => void; openBook: (book: Book) => void; savedIds: string[]; save: (id: string) => void }) { const starts = [bibleBooks[0], bibleBooks[1], bibleBooks[3], bibleBooks[39], bibleBooks[40], bibleBooks[44]]; return <><section className="hero-section" style={{ backgroundImage: `linear-gradient(90deg, rgba(15,31,43,.98) 0%, rgba(15,31,43,.87) 41%, rgba(15,31,43,.15) 100%),url(${heroImage})` }}><div className="hero-content"><Eyebrow number="01">Abertura editorial</Eyebrow><h1>Comece pelo mapa.<br /><em>Depois, siga a história.</em></h1><p className="hero-lede">A Bíblia não é uma página única. É um território de narrativas, poemas, cartas e visões — escrito ao longo do tempo por comunidades que tentavam compreender o mundo.</p><div className="hero-actions"><Button className="primary-action" onClick={() => go("library")}>Explorar os 66 livros <ArrowRight size={16} /></Button><button className="text-action" onClick={() => go("timeline")}>Ver linha do tempo <ChevronRight size={15} /></button></div></div><div className="hero-stamp"><span>ATLAS</span><strong>01</strong><small>de 66 livros</small></div><div className="hero-caption">Uma mesa de orientação<br />para leitura e contexto</div></section><section className="intro-band"><div className="intro-copy"><Eyebrow number="02">Uma biblioteca em camadas</Eyebrow><h2>Entender o todo<br /><em>sem apagar os detalhes.</em></h2><p>Use os caminhos abaixo para sair da sensação de “texto enorme” e entrar em uma sequência orientada: primeiro a paisagem, depois cada livro, suas perguntas e conexões.</p></div><div className="stats-grid"><Stat value="66" label="livros" icon={BookOpen} /><Stat value="2" label="testamentos" icon={Layers3} /><Stat value="12" label="gêneros e trilhas" icon={FileText} /><Stat value="8" label="períodos narrativos" icon={Clock3} /></div></section><section className="route-section"><div className="section-heading-row"><div><Eyebrow number="03">Primeiro percurso</Eyebrow><h2>Uma história em <em>movimento</em></h2></div><button className="outline-action" onClick={() => go("atlas")}>Abrir atlas visual <ExternalLink size={14} /></button></div><div className="route-layout"><RouteMap /><div className="route-notes">{[["01","Origens","Criação, ruptura e os primeiros deslocamentos."],["02","Aliança","Uma família se transforma em povo e memória."],["03","Reinos e exílio","Poder, profecia, crise e reconstrução."],["04","Jesus e comunidades","Novos caminhos entre casas, cidades e impérios."]].map(([number, title, desc]) => <div className="route-note" key={number}><span className="route-number">{number}</span><div><strong>{title}</strong><p>{desc}</p></div></div>)}</div></div></section><ExegesisSpotlight go={go} openBook={openBook} /><section className="library-preview"><div className="section-heading-row"><div><Eyebrow number="06">Pontos de entrada</Eyebrow><h2>Seis livros para<br /><em>começar a explorar</em></h2></div><button className="text-action text-action--dark" onClick={() => go("library")}>Ver todos os livros <ArrowRight size={15} /></button></div><div className="book-grid book-grid--preview">{starts.map(book => <BookCard key={book.id} book={book} onOpen={() => openBook(book)} saved={savedIds.includes(book.id)} onSave={() => save(book.id)} />)}</div></section><section className="quote-section"><div className="quote-mark">“</div><blockquote>A Bíblia é uma biblioteca: cada livro tem sua própria voz, mas nenhum livro está sozinho.</blockquote><span>Uma regra de leitura para esta plataforma</span></section></>; }

function Library(_props: { books: Book[]; search: string; setSearch: (v: string) => void; testament: string; setTestament: (v: string) => void; category: string; setCategory: string | ((v: string) => void); openBook: (book: Book) => void; savedIds: string[]; save: (id: string) => void }) { return <AdvancedBookLibrary />; }

function Timeline({ openBook }: { openBook: (book: Book) => void }) { const [selected, setSelected] = useState(0); const current = timeline[selected]; return <section className="page-section timeline-page"><div className="page-intro"><Eyebrow number="06">Cronologia interativa</Eyebrow><div className="page-title-row"><div><h1>O fio do <em>tempo</em></h1><p>Selecione um período para ver sua descrição, o movimento histórico e um livro de entrada relacionado.</p></div><div className="period-card"><span>8</span><small>períodos<br />indexados</small></div></div></div><div className="timeline-hero" style={{ backgroundImage: `linear-gradient(90deg,rgba(23,42,58,.94),rgba(23,42,58,.35)),url(${timelineImage})` }}><div><span className="timeline-kicker">Período selecionado · {current.date}</span><strong>{current.label}</strong><p>{current.description}</p><button className="primary-action" onClick={() => openBook(bibleBooks[Math.min(selected * 8, 65)])}>Abrir livro relacionado <ArrowRight size={16} /></button></div><div className="timeline-axis"><span>antes</span><span>agora</span><span>depois</span></div></div><div className="timeline-list">{timeline.map((item, index) => <button type="button" className={`timeline-item ${selected === index ? "is-selected" : ""}`} key={item.label} onClick={() => setSelected(index)} aria-pressed={selected === index}><div className="timeline-marker"><span>{String(index + 1).padStart(2, "0")}</span><i /></div><div className="timeline-content"><div className="timeline-meta"><span>{item.date}</span><span className="timeline-dot" /></div><h2>{item.label}</h2><p>{item.description}</p><span className="text-action text-action--dark">Selecionar período <ChevronRight size={14} /></span></div></button>)}</div></section>; }

function Atlas({ go, focusPlaceId, onFocusHandled }: { go: (view: View) => void; focusPlaceId?: string | null; onFocusHandled?: () => void }) { return <InteractiveAtlas go={view => go(view)} focusPlaceId={focusPlaceId} onFocusHandled={onFocusHandled} />; }

function Themes({ go }: { go: (label: string) => void }) { return <section className="page-section themes-page"><div className="page-intro"><Eyebrow number="08">Índice temático</Eyebrow><div className="page-title-row"><div><h1>As palavras que <em>atravessam</em></h1><p>Temas não são caixas fechadas. São fios que mudam de cor quando passam por livros, épocas e vozes diferentes.</p></div></div></div><div className="theme-layout"><div className="theme-intro-image" style={{ backgroundImage: `linear-gradient(0deg,rgba(23,42,58,.86),rgba(23,42,58,.04)),url(${studyImage})` }}><span>Fichas de estudo</span><strong>Escolha uma palavra.<br />Siga seus rastros.</strong></div><div className="theme-cards">{themes.map((item, index) => <button className={`theme-card theme-card--${item.tone}`} key={item.label} onClick={() => go(item.label)}><span className="theme-card-index">{String(index + 1).padStart(2, "0")}</span><div><h2>{item.label}</h2><p>{item.detail}</p><span className="theme-card-link">Ver livros relacionados <ArrowRight size={14} /></span></div></button>)}</div></div></section>; }

function Detail({ book, saved, save, close, openBook, note, setNote }: { book: Book; saved: boolean; save: () => void; close: () => void; openBook: (book: Book) => void; note: string; setNote: (v: string) => void }) { if (book.name === "Gênesis") return <GenesisRelationalDetail book={book} saved={saved} save={save} close={close} openBook={openBook} note={note} setNote={setNote} />; if (completeBookEntries[book.name]) return <CompleteBookDetail book={book} entry={completeBookEntries[book.name]} saved={saved} save={save} close={close} openBook={openBook} note={note} setNote={setNote} />; const [showContext, setShowContext] = useState(true); const index = bibleBooks.findIndex(item => item.id === book.id); const previous = bibleBooks[index - 1]; const next = bibleBooks[index + 1]; return <section className="book-detail-page"><div className="book-detail-top"><button className="back-action" onClick={close}><ArrowLeft size={15} /> Voltar para biblioteca</button><button className={`save-detail ${saved ? "is-saved" : ""}`} onClick={save}>{saved ? <BookmarkCheck size={15} /> : <Bookmark size={15} />}{saved ? "Salvo na mesa" : "Salvar livro"}</button></div><div className="book-detail-header"><div className="detail-index">{String(index + 1).padStart(2, "0")} <span>/ 66</span></div><Badge book={book} /><h1>{book.name}</h1><p className="detail-deck">{book.summary} Ao lê-lo, acompanhe também a pergunta que organiza sua voz: que tipo de comunidade, memória ou esperança está sendo formada aqui?</p><div className="detail-meta-grid"><div><span>Gênero</span><strong>{book.category}</strong></div><div><span>Capítulos</span><strong>{book.chapters}</strong></div><div><span>Período</span><strong>{book.period}</strong></div><div><span>Autoria</span><strong>{book.author}</strong></div></div></div><div className="detail-layout"><article className="detail-main"><div className="detail-section"><Eyebrow number="01">Mapa do livro</Eyebrow><h2>O que este livro está <em>tentando fazer?</em></h2><p>{book.summary} Observe não apenas os acontecimentos, mas também sua forma de {book.category.toLowerCase()} e o efeito que ela produz no leitor.</p></div><div className="detail-section detail-section--split"><div><Eyebrow number="02">Fios de leitura</Eyebrow><h2>Temas que deixam <em>rastros</em></h2><div className="detail-themes">{book.themes.map(theme => <span key={theme}># {theme}</span>)}</div></div><div className="detail-route-card"><Compass size={17} /><span>Próxima conexão</span><strong>{next?.name || "Volte ao início"}</strong><small>O livro seguinte amplia ou desloca a pergunta.</small></div></div><div className="detail-section"><Eyebrow number="03">Contexto e autoria</Eyebrow><button className="context-toggle" onClick={() => setShowContext(!showContext)}><span>{showContext ? "Recolher contexto" : "Mostrar contexto"}</span><ChevronDown size={16} className={showContext ? "rotate" : ""} /></button>{showContext && <div className="context-panel"><div><Users size={17} /><strong>Quem fala</strong><p>{book.author}. A informação combina tradição e cautela acadêmica quando a autoria é debatida.</p></div><div><Clock3 size={17} /><strong>Quando se passa</strong><p>{book.period}. As datas são aproximadas e podem refletir mundo narrado ou composição.</p></div><div><FileText size={17} /><strong>Como ler</strong><p>Deixe o gênero literário orientar sua atenção e suas perguntas.</p></div></div>}</div><div className="detail-section note-section"><Eyebrow number="04">Anotação de margem</Eyebrow><h2>O que você quer <em>guardar?</em></h2><textarea value={note} onChange={e => setNote(e.target.value)} placeholder="Escreva uma pergunta, conexão ou observação..." aria-label="Anotação para o livro" /><div className="note-foot"><span>{note ? `${note.length} caracteres nesta sessão` : "As anotações ficam nesta sessão"}</span><button onClick={() => toast.success("Anotação guardada nesta sessão.")}><Check size={14} /> Guardar nota</button></div></div></article><aside className="detail-aside"><div className="aside-card aside-card--quote"><Quote size={24} /><p>“Leia este livro como uma voz situada: com época, tensão, forma e intenção.”</p><span>Regra de leitura</span></div><div className="aside-card"><span className="aside-label">Navegação contínua</span><div className="book-switcher">{previous ? <button onClick={() => openBook(previous)}><ArrowLeft size={14} /><small>anterior</small><strong>{previous.name}</strong></button> : <div />}{next ? <button onClick={() => openBook(next)}><small>próximo</small><strong>{next.name}</strong></button> : <div />}</div></div><div className="aside-progress"><span>Explorando a biblioteca</span><strong>{Math.round(((index + 1) / 66) * 100)}%</strong><div><i style={{ width: `${((index + 1) / 66) * 100}%` }} /></div><small>Livro {index + 1} de 66</small></div></aside></div></section>; }
function CompleteBookDetail({ book, entry, saved, save, close, openBook, note, setNote }: { book: Book; entry: CompleteBook; saved: boolean; save: () => void; close: () => void; openBook: (book: Book) => void; note: string; setNote: (v: string) => void }) { const [activeSection, setActiveSection] = useState<"panorama" | "estrutura" | "camadas" | "relacoes" | "fontes">("panorama"); const index = bibleBooks.findIndex(item => item.id === book.id); const previous = bibleBooks[index - 1]; const next = bibleBooks[index + 1]; const tabs = [{ id: "panorama", label: "Panorama" }, { id: "estrutura", label: "Estrutura" }, { id: "camadas", label: "Camadas de leitura" }, { id: "relacoes", label: "Relações" }, { id: "fontes", label: "Fontes" }] as const; const jump = (id: typeof activeSection) => { setActiveSection(id); window.setTimeout(() => document.getElementById(`complete-section-${id}`)?.scrollIntoView({ behavior: "smooth", block: "start" }), 20); }; return <section className="complete-book-page"><div className="complete-book-top"><button className="back-action" onClick={close}><ArrowLeft size={15} /> Voltar para os 66 livros</button><div className="complete-book-top-actions"><span>Verbete aprofundado · {index + 1}/66</span><button className={`save-detail ${saved ? "is-saved" : ""}`} onClick={save}>{saved ? <BookmarkCheck size={15} /> : <Bookmark size={15} />}{saved ? "Salvo" : "Salvar"}</button></div></div><header className="complete-book-hero"><div className="complete-book-kicker"><Badge book={book} /><span>{entry.identity.genre}</span></div><h1>{entry.name}</h1><p className="complete-book-opening">{entry.opening}</p><div className="complete-book-ask"><Compass size={18} /><div><span>Pergunta central do verbete</span><strong>{entry.identity.centralQuestion}</strong></div></div></header><nav className="complete-book-tabs" aria-label={`Seções do verbete de ${entry.name}`} role="tablist">{tabs.map(tab => <button key={tab.id} className={activeSection === tab.id ? "is-active" : ""} onClick={() => jump(tab.id)} role="tab" aria-selected={activeSection === tab.id}>{tab.label}<ChevronRight size={13} /></button>)}</nav><div className="complete-book-layout"><aside className="complete-book-sidebar"><div className="complete-sidebar-label">Índice interno</div>{tabs.map((tab, tabIndex) => <button key={tab.id} className={activeSection === tab.id ? "is-active" : ""} onClick={() => jump(tab.id)}><span>{String(tabIndex + 1).padStart(2, "0")}</span><strong>{tab.label}</strong></button>)}<div className="complete-sidebar-note"><FileText size={15} /><span>As etiquetas indicam quando uma afirmação é textual, confessional, pentecostal ou acadêmica.</span></div></aside><main className="complete-book-main"><section id="complete-section-panorama" className="complete-content-section"><Eyebrow number="01">Identidade e contexto</Eyebrow><h2>Antes de interpretar,<br /><em>localize a voz.</em></h2><div className="identity-grid"><div><span>Cânon</span><strong>{entry.identity.canon}</strong></div><div><span>Gênero</span><strong>{entry.identity.genre}</strong></div><div><span>Período</span><strong>{entry.identity.period}</strong></div><div><span>Cenário</span><strong>{entry.identity.setting}</strong></div><div><span>Autoria tradicional</span><strong>{entry.identity.traditionalAuthor}</strong></div><div><span>Perspectiva acadêmica</span><strong>{entry.identity.academicView}</strong></div></div></section><section id="complete-section-estrutura" className="complete-content-section"><Eyebrow number="02">Mapa interno</Eyebrow><h2>O livro em <em>movimento.</em></h2><div className="structure-stack">{entry.structure.map((block, blockIndex) => <article key={block.range}><div className="structure-range">{block.range}</div><div><h3>{block.title}</h3><p>{block.summary}</p></div><span>{String(blockIndex + 1).padStart(2, "0")}</span></article>)}</div><div className="themes-deep-grid">{entry.themes.map(theme => <article key={theme.label}><span># tema</span><h3>{theme.label}</h3><p>{theme.explanation}</p></article>)}</div></section><section id="complete-section-camadas" className="complete-content-section"><Eyebrow number="03">Quatro camadas</Eyebrow><h2>Não misture <em>autoridades.</em></h2><p className="section-lede">Uma enciclopédia confiável precisa mostrar de onde vem cada afirmação. Leia o mesmo livro por quatro lentes e observe onde elas convergem ou divergem.</p><div className="authority-grid">{entry.layers.map(layer => <article className={`authority-card authority-card--${layer.tone}`} key={layer.label}><div className="authority-card-top"><span>{layer.label}</span><i /></div><p>{layer.text}</p><strong>{layer.refs}</strong></article>)}</div></section><section id="complete-section-relacoes" className="complete-content-section"><Eyebrow number="04">Relações vivas</Eyebrow><h2>Nenhum livro<br /><em>está sozinho.</em></h2><div className="deep-entity-columns"><div><span className="deep-column-label">Pessoas e papéis</span>{entry.people.map(person => <div className="deep-entity-row" key={person.name}><Users size={15} /><div><strong>{person.name}</strong><small>{person.role}</small></div></div>)}</div><div><span className="deep-column-label">Lugares e função</span>{entry.places.map(place => <div className="deep-entity-row" key={place.name}><Map size={15} /><div><strong>{place.name}</strong><small>{place.note}</small></div></div>)}</div></div><div className="connection-grid"><span className="deep-column-label">Conexões canônicas</span>{entry.connections.map(connection => { const target = bibleBooks.find(item => item.name === connection.book); return <button key={connection.book} onClick={() => target ? openBook(target) : toast.info(`${connection.book} será adicionado à próxima coleção.`)}><div><span>{connection.label}</span><strong>{connection.book}</strong><small>{connection.reason}</small></div><ArrowRight size={15} /></button>; })}</div></section><section id="complete-section-fontes" className="complete-content-section"><Eyebrow number="05">Fontes e continuação</Eyebrow><h2>Continue a <em>investigação.</em></h2><p className="section-lede">As fontes abaixo são pontos de partida. O verbete apresenta uma síntese editorial e não substitui uma Bíblia de estudo, comentário especializado ou documento oficial completo.</p><div className="source-list">{entry.sources.map(source => <a key={source.url} href={source.url} target="_blank" rel="noreferrer"><ExternalLink size={15} /><span>{source.label}</span><ArrowRight size={14} /></a>)}</div><div className="complete-note"><Eyebrow>Anotação de margem</Eyebrow><textarea value={note} onChange={e => setNote(e.target.value)} placeholder="Guarde uma pergunta, conexão ou observação sobre este livro..." aria-label={`Anotação sobre ${entry.name}`} /><div><span>{note ? `${note.length} caracteres nesta sessão` : "As notas ficam nesta sessão"}</span><button onClick={() => toast.success("Anotação guardada nesta sessão.")}><Check size={14} /> Guardar</button></div></div></section></main><aside className="complete-book-right-rail"><div className="right-rail-card"><span>Navegação contínua</span>{previous && <button onClick={() => openBook(previous)}><ArrowLeft size={14} /><small>anterior</small><strong>{previous.name}</strong></button>}{next && <button onClick={() => openBook(next)}><small>próximo</small><strong>{next.name}</strong><ArrowRight size={14} /></button>}</div><div className="right-rail-card right-rail-card--progress"><span>Índice explorado</span><strong>{Math.round(((index + 1) / 66) * 100)}%</strong><div><i style={{ width: `${((index + 1) / 66) * 100}%` }} /></div><small>Livro {index + 1} de 66 · modelo aprofundado</small></div></aside></div></section>; }

function StudyHub({ openLesson }: { openLesson: (module: StudyModule, lesson: Lesson) => void }) { const [active, setActive] = useState<StudyModule>(studyModules[0]); return <section className="study-hub page-section"><div className="page-intro study-intro"><Eyebrow number="09">Curso enciclopédico</Eyebrow><div className="study-title-row"><div><h1>Não apenas leia.<br /><em>Aprenda a pensar com a Bíblia.</em></h1><p>O percurso foi organizado como uma biblioteca comentada: oito módulos, 24 aulas, vocabulário, debates, contexto histórico e ferramentas para continuar a pesquisa.</p></div><div className="course-meter"><span className="course-meter-ring">0%</span><div><strong>Comece pelo módulo 01</strong><small>Fundamentos da Bíblia e formação do cânon</small></div></div></div></div><div className="study-layout"><aside className="module-index"><div className="module-index-label">Índice do curso</div>{studyModules.map(module => <button key={module.id} className={`module-index-item ${active.id === module.id ? "is-active" : ""}`} onClick={() => setActive(module)}><span>{module.number}</span><div><strong>{module.title}</strong><small>{module.duration}</small></div><ChevronRight size={14} /></button>)}</aside><div className="module-view"><div className={`module-hero module-hero--${active.tone}`}><div><span className="module-kicker">Módulo {active.number} · {active.level}</span><h2>{active.title}</h2><p>{active.description}</p></div><div className="module-meta"><span>{active.lessons.length} aulas</span><span>{active.duration}</span></div></div><div className="lesson-list"><div className="lesson-list-head"><div><Eyebrow>Aulas e oficinas</Eyebrow><h3>{active.subtitle}</h3></div><span>0/{active.lessons.length} concluídas</span></div>{active.lessons.map((lesson, index) => <button className="lesson-row" key={lesson.id} onClick={() => openLesson(active, lesson)}><span className="lesson-number">{String(index + 1).padStart(2, "0")}</span><span className="lesson-icon"><BookOpen size={15} /></span><span className="lesson-copy"><strong>{lesson.title}</strong><small>{lesson.kind} · {lesson.duration}</small></span><span className="lesson-open"><span>Começar</span><ArrowRight size={15} /></span></button>)}</div></div></div><div className="study-method-strip"><div><Compass size={18} /><strong>Aprenda em camadas</strong><span>panorama → contexto → texto → debate</span></div><div><CircleHelp size={18} /><strong>Sem respostas fáceis</strong><span>distinguimos consenso, tradição e hipótese</span></div><div><Bookmark size={18} /><strong>Monte sua mesa</strong><span>salve aulas, notas e perguntas</span></div></div></section>; }

function LessonDetail({ module, lesson, close }: { module: StudyModule; lesson: Lesson; close: () => void }) { const [done, setDone] = useState(false); return <section className="lesson-detail page-section"><button className="back-action" onClick={close}><ArrowLeft size={15} /> Voltar para o curso</button><div className="lesson-detail-head"><div className={`lesson-flag lesson-flag--${module.tone}`}>Módulo {module.number} · {lesson.kind}</div><h1>{lesson.title}</h1><p>{module.subtitle} · {lesson.duration}</p></div><div className="lesson-detail-layout"><article className="lesson-article"><Eyebrow number="01">Aula em profundidade</Eyebrow><p className="lesson-lede">{lesson.body}</p><div className="lesson-key-box"><div className="lesson-key-head"><Layers3 size={17} /><strong>Ideias para guardar</strong></div>{lesson.keyPoints.map((point, index) => <div className="lesson-key-point" key={point}><span>{String(index + 1).padStart(2, "0")}</span><p>{point}</p></div>)}</div><div className="lesson-reflection"><Eyebrow number="02">Perguntas de leitura</Eyebrow><h2>Não termine com uma <em>resposta pronta.</em></h2><p>Que diferença faria ler este assunto a partir do contexto histórico, da forma literária e da experiência de uma comunidade específica?</p><textarea placeholder="Anote sua pergunta de pesquisa..." aria-label="Pergunta de pesquisa" /></div></article><aside className="lesson-aside"><div className="lesson-source-card"><span>Fonte de orientação</span><strong>{lesson.source}</strong><small>Use esta indicação como ponto de partida. A plataforma não substitui uma edição crítica ou comentário especializado.</small></div><button className={`lesson-complete ${done ? "is-done" : ""}`} onClick={() => setDone(!done)}>{done ? <><Check size={16} /> Aula marcada como lida</> : <><Check size={16} /> Marcar como lida</>}</button><div className="lesson-next-card"><span>Próxima camada</span><strong>{module.lessons[(module.lessons.findIndex(item => item.id === lesson.id) + 1) % module.lessons.length].title}</strong><ChevronRight size={15} /></div></aside></div></section>; }

function PeopleHub({ go }: { go: (label: string) => void }) { return <section className="people-page page-section"><div className="page-intro"><Eyebrow number="10">Quem povoa a narrativa</Eyebrow><div className="page-title-row"><div><h1>Pessoas, povos<br />e <em>instituições</em></h1><p>Uma enciclopédia de personagens não é uma lista de heróis. É um mapa de relações, poder, memória, conflito e representação.</p></div><div className="result-count"><strong>{people.length}</strong><span>entradas iniciais</span></div></div></div><div className="people-grid">{people.map((person, index) => <article className="person-card" key={person.name}><div className="person-top"><span>{String(index + 1).padStart(2, "0")}</span><span>{person.refs}</span></div><div className="person-seal"><Users size={20} /></div><span className="person-type">{person.type}</span><h2>{person.name}</h2><p>{person.description}</p><div className="person-tags">{person.tags.map(tag => <button key={tag} onClick={() => go(tag)}>#{tag}</button>)}</div></article>)}</div><div className="people-note"><Quote size={19} /><p>“Personagem” é uma categoria literária e histórica: às vezes sabemos pouco sobre a pessoa fora do texto, mas podemos observar muito sobre como ela é narrada.</p></div></section>; }

function CanonHub({ go }: { go: (id: string) => void }) { return <section className="canon-page page-section"><div className="page-intro"><Eyebrow number="11">Cânon e transmissão</Eyebrow><div className="page-title-row"><div><h1>Uma biblioteca,<br /><em>várias molduras</em></h1><p>Comparar cânones é compreender que listas, ordens e tradições de leitura também moldam o que uma comunidade considera o “todo” das Escrituras.</p></div><div className="canon-figure"><strong>4</strong><span>molduras<br />históricas</span></div></div></div><div className="canon-table-wrap"><table className="canon-table"><thead><tr><th>Tradição</th><th>Antigo / Tanakh</th><th>Novo</th><th>Total</th><th>Nota de orientação</th></tr></thead><tbody>{canonComparison.map(row => <tr key={row.tradition}><td><strong>{row.tradition}</strong></td><td>{row.old}</td><td>{row.new}</td><td className="canon-total">{row.total}</td><td>{row.note}</td></tr>)}</tbody></table></div><div className="canon-lower"><div className="canon-essay"><Eyebrow number="12">Como usar esta comparação</Eyebrow><h2>Diferença não é <em>ruído.</em></h2><p>O número de livros é apenas a camada mais visível. A ordem, a liturgia, a autoridade da tradição e a maneira de relacionar Escritura e comunidade também mudam. Ao estudar um livro, registre qual cânon e qual tradição de interpretação estão em jogo.</p><button className="primary-action primary-action--dark" onClick={() => go("fundamentos")}>Estudar formação do cânon <ArrowRight size={16} /></button></div><div className="canon-cards"><button onClick={() => go("manuscritos")}><FileText size={18} /><strong>Manuscritos</strong><span>Veja como cópias, versões e variantes entram na pesquisa.</span><ArrowRight size={14} /></button><button onClick={() => go("interpretacao")}><CircleHelp size={18} /><strong>Interpretação</strong><span>Compare métodos sem transformar tradição em caricatura.</span><ArrowRight size={14} /></button></div></div></section>; }

function GlossaryHub({ openBook, go }: { openBook?: (book: Book) => void; go?: (view: View) => void }) { const [query, setQuery] = useState(""); const normalized = query.toLowerCase().trim(); const bookResults = bibleBooks.filter(book => !normalized || [book.name, book.author, book.category, book.summary, ...book.themes].join(" ").toLowerCase().includes(normalized)); const theologyResults = theologyEntries.filter(entry => !normalized || [entry.title, entry.category, entry.statement, entry.pentecostalReading].join(" ").toLowerCase().includes(normalized)); const glossaryResults = glossary.filter(([term, definition]) => !normalized || `${term} ${definition}`.toLowerCase().includes(normalized)); const peopleResults = people.filter(person => !normalized || `${person.name} ${person.type} ${person.description} ${person.tags.join(" ")}`.toLowerCase().includes(normalized)); const resultCount = bookResults.length + theologyResults.length + glossaryResults.length + peopleResults.length; return <section className="glossary-page page-section"><div className="page-intro"><Eyebrow number="13">Busca global</Eyebrow><div className="page-title-row"><div><h1>Encontre um<br /><em>verbete.</em></h1><p>Pesquise em toda a enciclopédia: livros, personagens, temas, teologia pentecostal e conceitos de contexto.</p></div><div className="result-count"><strong>{resultCount}</strong><span>resultados</span></div></div></div><div className="glossary-toolbar global-search-toolbar"><Search size={17} /><Input autoFocus value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar livro, pessoa, lugar, tema ou doutrina..." aria-label="Buscar em toda a enciclopédia" /><span>{query ? `${resultCount} encontrados` : "Digite para explorar"}</span></div>{!query && <div className="search-suggestion-row"><button onClick={() => setQuery("Espírito Santo")}>Espírito Santo</button><button onClick={() => setQuery("aliança")}>Aliança</button><button onClick={() => setQuery("Paulo")}>Paulo</button><button onClick={() => setQuery("santificação")}>Santificação</button></div>}<div className="global-results">{bookResults.length > 0 && <section className="global-result-group"><div className="global-result-heading"><Eyebrow>Livros</Eyebrow><span>{bookResults.length}</span></div><div className="global-result-list">{bookResults.slice(0, normalized ? 12 : 6).map(book => <button key={book.id} onClick={() => openBook?.(book)}><span className="global-result-index">{testamentShort(book.testament)}</span><div><strong>{book.name}</strong><small>{book.category} · {book.author}</small><p>{book.summary}</p></div><ArrowRight size={15} /></button>)}</div></section>}{peopleResults.length > 0 && <section className="global-result-group"><div className="global-result-heading"><Eyebrow>Pessoas e povos</Eyebrow><span>{peopleResults.length}</span></div><div className="global-chip-list">{peopleResults.map(person => <button key={person.name} onClick={() => setQuery(person.name)}><Users size={14} /><span>{person.name}</span><small>{person.type}</small></button>)}</div></section>}{theologyResults.length > 0 && <section className="global-result-group"><div className="global-result-heading"><Eyebrow>Teologia IDB</Eyebrow><span>{theologyResults.length}</span></div><div className="global-result-list global-result-list--theology">{theologyResults.map(entry => <button key={entry.id} onClick={() => setQuery(entry.title)}><span className="global-result-index">{entry.number}</span><div><strong>{entry.title}</strong><small>{entry.category}</small><p>{entry.statement}</p></div><ArrowRight size={15} /></button>)}</div></section>}{glossaryResults.length > 0 && <section className="global-result-group"><div className="global-result-heading"><Eyebrow>Glossário e contexto</Eyebrow><span>{glossaryResults.length}</span></div><div className="glossary-grid">{glossaryResults.slice(0, 12).map(([term, definition], index) => <article key={term}><span>{String(index + 1).padStart(2, "0")}</span><h2>{term}</h2><p>{definition}</p><button onClick={() => setQuery(term)}>Explorar contexto <ArrowRight size={14} /></button></article>)}</div></section>}{query && resultCount === 0 && <div className="empty-state"><CircleHelp size={30} /><h3>Nenhum verbete encontrado</h3><p>Tente outro nome, tema, período ou doutrina.</p></div>}</div></section>; }
function MobileBottomNav({ view, go, savedCount: _savedCount }: { view: View; go: (view: View) => void; savedCount?: number }) { const items: { id: View; label: string; icon: typeof Compass; badge?: string }[] = [{ id: "overview", label: "Início", icon: Compass }, { id: "library", label: "Livros", icon: BookOpen, badge: "66" }, { id: "people", label: "Pessoas", icon: Users }, { id: "atlas", label: "Lugares", icon: Map }, { id: "search", label: "Buscar", icon: Search }]; return <nav className="mobile-bottom-nav" aria-label="Navegação rápida da enciclopédia">{items.map((item, index) => <button key={`${item.label}-${index}`} className={`mobile-bottom-link ${view === item.id ? "is-active" : ""}`} onClick={() => go(item.id)} aria-label={item.label}><span className="mobile-bottom-icon"><item.icon size={18} />{item.badge && <small>{item.badge}</small>}</span><span>{item.label}</span></button>)}</nav>; }
function EncyclopediaHub({ go }: { go: (view: View) => void }) { const [activeId, setActiveId] = useState(advancedDossiers[0].id); const active = advancedDossiers.find(item => item.id === activeId) || advancedDossiers[0]; return <section className="encyclopedia-page page-section advanced-encyclopedia"><div className="page-intro encyclopedia-intro"><Eyebrow number="09">Centro de dossiês avançados</Eyebrow><div className="encyclopedia-title-row"><div><h1>Estude a Bíblia<br /><em>com densidade.</em></h1><p>Não é um resumo devocional. É uma obra de referência para cruzar historiografia, arqueologia, crítica literária, línguas, fontes primárias, teologia e tradição pentecostal.</p></div><div className="encyclopedia-index-mark"><strong>{advancedDossiers.length}</strong><span>dossiês<br />históricos</span></div></div></div><div className="advanced-stance"><ShieldCheck size={18} /><div><strong>Modo avançado</strong><span>O texto separa evidência material, reconstrução histórica, leitura literária, interpretação teológica e posição confessional.</span></div><button onClick={() => go("atlas")}>Abrir atlas real <Map size={15} /></button></div><div className="advanced-dossier-layout"><aside className="advanced-dossier-index"><div><Eyebrow>Dossiês por período</Eyebrow><strong>{advancedDossiers.length}<span> eixos</span></strong></div>{advancedDossiers.map((dossier, index) => <button key={dossier.id} className={activeId === dossier.id ? "is-active" : ""} onClick={() => setActiveId(dossier.id)}><span>{String(index + 1).padStart(2, "0")}</span><div><strong>{dossier.title}</strong><small>{dossier.date}</small></div><ChevronRight size={14} /></button>)}</aside><article className="advanced-dossier-detail"><div className="advanced-dossier-top"><div><span>{active.period} · {active.date}</span><h2>{active.title}</h2></div><span className="confidence-chip"><ShieldCheck size={13} /> {active.confidence}</span></div><p className="advanced-thesis">{active.thesis}</p><div className="advanced-dossier-columns"><div><span className="advanced-label">Perguntas historiográficas</span>{active.questions.map(question => <p key={question}>↳ {question}</p>)}</div><div><span className="advanced-label">Debates em aberto</span>{active.debates.map(debate => <p key={debate}>↳ {debate}</p>)}</div></div><div className="advanced-source-row"><div><span className="advanced-label">Fontes e bibliografia</span><strong>{active.sources.join(" · ")}</strong></div><div><span className="advanced-label">Entidades relacionadas</span><strong>{active.entities.join(" · ")}</strong></div></div></article></div><div className="advanced-hub-foot"><button onClick={() => go("atlas")}>Explorar lugares e coordenadas <Map size={15} /></button><button onClick={() => go("library")}>Cruzar com os 66 livros <BookOpen size={15} /></button><button onClick={() => go("apocalypse")}>Ir para Apocalipse e escatologia <Eye size={15} /></button></div><div className="encyclopedia-note"><Compass size={19} /><p><strong>Como pesquisar:</strong> comece pelo problema histórico, identifique quais dados são diretos, compare modelos concorrentes e só então relacione o dossiê com a leitura teológica.</p></div><PentecostalReference /></section>; }
function PentecostalReference() { const [category, setCategory] = useState("Todos"); const [active, setActive] = useState<TheologyEntry>(theologyEntries[0]); const filtered = theologyEntries.filter(entry => category === "Todos" || entry.category === category); return <section id="teologia-idb" className="theology-reference"><div className="theology-reference-head"><div><Eyebrow number="14">Teologia IDB · tradição pentecostal</Eyebrow><h2>Doutrina, experiência<br /><em>e vida no Espírito.</em></h2><p>Verbetes para consultar a fé da Igreja de Deus no Brasil em diálogo com a Bíblia, a tradição pentecostal e a pesquisa histórica. Cada entrada identifica o tipo de afirmação apresentado.</p></div><div className="theology-seal"><strong>14</strong><span>eixos<br />doutrinários</span></div></div><div className="theology-category-bar">{theologyCategories.map(item => <button key={item} className={category === item ? "is-active" : ""} onClick={() => { setCategory(item); const next = theologyEntries.find(entry => item === "Todos" || entry.category === item); if (next) setActive(next); }}>{item}</button>)}</div><div className="theology-layout"><div className="theology-entry-list">{filtered.map(entry => <button key={entry.id} className={`theology-entry-row ${active.id === entry.id ? "is-active" : ""}`} onClick={() => setActive(entry)}><span>{entry.number}</span><div><strong>{entry.title}</strong><small>{entry.category}</small></div><ArrowRight size={14} /></button>)}</div><article className="theology-entry-detail"><div className="theology-detail-kicker"><span>{active.number}</span><span>{active.category}</span></div><h3>{active.title}</h3><p className="theology-statement">{active.statement}</p><div className="theology-detail-block"><span>Base bíblica</span><strong>{active.biblicalBasis}</strong></div><div className="theology-detail-block"><span>Leitura pentecostal</span><p>{active.pentecostalReading}</p></div><div className="theology-detail-block"><span>Distinção metodológica</span><p>{active.distinction}</p></div><div className="theology-source"><FileText size={15} /><span>Fonte de referência</span><strong>{active.source}</strong></div></article></div><div className="theology-legend"><span><i className="legend-dot legend-dot--gold" /> Declaração de fé / posição confessional</span><span><i className="legend-dot legend-dot--wine" /> Leitura pentecostal</span><span><i className="legend-dot legend-dot--blue" /> Contexto bíblico e histórico</span></div></section>; }
